function bind(){
  $$('[data-route]').forEach(b=>b.onclick=()=>{state.route=b.dataset.route;state.moreMenu=false;state.profileMenu=false;location.hash=`#/${state.route}`;render();});
  $$('[data-action="toggle-profile"]').forEach(b=>b.onclick=()=>{state.profileMenu=!state.profileMenu;state.moreMenu=false;render();});
  $$('[data-action="open-more"]').forEach(b=>b.onclick=()=>{state.moreMenu=true;state.profileMenu=false;render();});
  $$('[data-action="close-more"]').forEach(b=>b.onclick=()=>{state.moreMenu=false;render();});
  $$('[data-preview-role]').forEach(b=>b.onclick=()=>{state.previewRole=b.dataset.previewRole||null;state.profileMenu=false;state.route='dashboard';render();});
  $$('[data-workspace-role]').forEach(b=>b.onclick=()=>runAction(async()=>{const role=b.dataset.workspaceRole;if(!rolesOf().includes(role))return;state.workspaceRole=role;sessionStorage.setItem('studiodeskWorkspaceRole',role);state.previewRole=null;state.profileMenu=false;await updateUserProfile(state.authUser.uid,{defaultWorkspace:role});state.route='dashboard';location.hash='#/dashboard';await startWorkspace();render();},b));
  $$('[data-toggle-password]').forEach(b=>b.onclick=()=>{const input=b.parentElement?.querySelector('input');if(!input)return;const show=input.type==='password';input.type=show?'text':'password';b.textContent=show?'Hide':'Show';b.setAttribute('aria-label',show?'Hide password':'Show password');});
  $$('[data-action="signout"]').forEach(b=>b.onclick=()=>runAction(async()=>{await signOutUser();sessionStorage.removeItem('studiodeskWorkspaceRole');state.route='public';state.previewRole=null;state.workspaceRole=null;state.profileMenu=false;history.replaceState(null,'',location.pathname);render();},b));
  $$('[data-action="show-login"]').forEach(b=>b.onclick=()=>{state.route='login';location.hash='#/login';render();});
  $$('[data-action="back-public"]').forEach(b=>b.onclick=()=>{state.route='public';history.replaceState(null,'',location.pathname);render();});
  $$('[data-action="public-services"]').forEach(b=>b.onclick=()=>$('#public-services')?.scrollIntoView({behavior:'smooth'}));
  $$('[data-action="request-service"]').forEach(b=>{const service=[...state.publicServices,...currentServices()].find(x=>x.id===b.dataset.serviceId);b.onclick=()=>openModal(publicRequestModal(service));});
  $$('[data-action="client-request"]').forEach(b=>b.onclick=()=>openModal(publicRequestModal(null)));

  $$('[data-tour-prev]').forEach(b=>b.onclick=()=>{if(state.tourStep>0){state.tourStep--;render();}});
  $$('[data-tour-next]').forEach(b=>b.onclick=()=>runAction(async()=>{const requested=state.profile?.requestedRole,role=rolesOf().length?effectiveRole():(requested==='client'?'client':'worker'),key=['owner','admin'].includes(role)?'owner':role==='client'?'client':'worker',steps=onboardingByRole[key]||onboardingByRole.worker;if(state.tourStep<steps.length-1){state.tourStep++;render();return;}await markOnboardingComplete();state.profile={...state.profile,onboardingComplete:true,onboardingEligible:false};state.tourStep=0;toast('Orientation complete. StudioDesk will not show it again.');render();},b));

  $('#login-form')?.addEventListener('submit',e=>runAction(async()=>{e.preventDefault();const fd=new FormData(e.currentTarget);await signInWithEmail(fd.get('email'),fd.get('password'));},e.currentTarget.querySelector('button[type="submit"]')));
  $('#signup-form')?.addEventListener('submit',e=>runAction(async()=>{e.preventDefault();const fd=new FormData(e.currentTarget);if(fd.get('password')!==fd.get('confirmPassword'))throw new Error('Passwords do not match.');await registerWithEmail(fd.get('email'),fd.get('password'));state.profile=await createPendingProfile({name:fd.get('name'),email:fd.get('email'),requestedRole:fd.get('requestedRole')});await recordTermsAcceptance({termsVersion:'studio-terms-v1',scope:'portal-signup'});state.route='dashboard';state.signupMode=false;state.tourStep=0;render();},e.currentTarget.querySelector('button[type="submit"]')));
  $$('[data-action="google-login"]').forEach(b=>b.onclick=()=>runAction(async()=>{await signInWithGoogle();let existing=await getCurrentUserProfile().catch(()=>null);if(!existing){if(!confirm('Create a new StudioDesk account with Google and accept the current portal terms?')){await signOutUser();return;}existing=await ensureGoogleProfile({requestedRole:'client'});await recordTermsAcceptance({termsVersion:'studio-terms-v1',scope:'google-portal-signup'});state.profile=existing;state.route='dashboard';state.tourStep=0;render();}},b));
  $$('[data-action="forgot-password"]').forEach(b=>b.onclick=()=>runAction(async()=>{const email=prompt('Enter your email address');if(!email)return;await resetPassword(email);toast('Password reset email sent.');},b));
  $$('[data-action="create-self-profile"]').forEach(b=>b.onclick=()=>runAction(async()=>{state.profile=await createPendingProfile({name:state.authUser?.displayName||state.authUser?.email?.split('@')[0]||'New user',email:state.authUser?.email||'',requestedRole:'worker'});state.tourStep=0;await startWorkspace();render();},b));
  $$('[data-action="toggle-signup"]').forEach(b=>b.onclick=()=>{state.signupMode=!state.signupMode;state.loginMessage='';render();});

  $$('[data-action="seed-workspace"]').forEach(b=>b.onclick=()=>runAction(async()=>{await ensureWorkspaceSeed();state.settings=await getStudioSettings();toast('Editable starter catalogue created.');},b));
  $$('[data-action="open-new-project"]').forEach(b=>b.onclick=()=>openModal(newProjectModal()));
  $$('[data-action="toggle-archived-projects"]').forEach(b=>b.onclick=()=>{state.showArchivedProjects=!state.showArchivedProjects;render();});
  $$('[data-action="toggle-archived-clients"]').forEach(b=>b.onclick=()=>{state.showArchivedClients=!state.showArchivedClients;render();});
  $$('[data-action="toggle-archived-tasks"]').forEach(b=>b.onclick=()=>{state.showArchivedTasks=!state.showArchivedTasks;render();});
  $$('[data-action="toggle-archived-packages"]').forEach(b=>b.onclick=()=>{state.showArchivedPackages=!state.showArchivedPackages;render();});
  $$('[data-action="toggle-archived-contracts"]').forEach(b=>b.onclick=()=>{state.showArchivedContracts=!state.showArchivedContracts;render();});
  $$('[data-service-filter]').forEach(b=>b.onclick=()=>{state.serviceFilter=b.dataset.serviceFilter;render();});
  $$('[data-services-tab]').forEach(b=>b.onclick=()=>{state.servicesTab=b.dataset.servicesTab;render();});
  $$('[data-action="add-workflow"]').forEach(b=>b.onclick=()=>openModal(workflowModal()));
  $$('[data-action="add-service"]').forEach(b=>b.onclick=()=>openModal(serviceModal()));
  $$('[data-action="add-category"]').forEach(b=>b.onclick=()=>openModal(categoryModal()));
  $$('[data-action="new-package"]').forEach(b=>b.onclick=()=>openModal(packageModal()));
  $$('[data-action="custom-package"]').forEach(b=>b.onclick=()=>openModal(packageModal()));
  $$('[data-action="add-client"]').forEach(b=>b.onclick=()=>openModal(clientModal()));
  $$('[data-action="invite-worker"]').forEach(b=>b.onclick=()=>openModal(inviteModal()));
  $$('[data-action="new-expense"]').forEach(b=>b.onclick=()=>openModal(expenseModal()));
  $$('[data-action="global-contract"]').forEach(b=>{b.onclick=()=>{const p=projects().find(canManageProject)||projects()[0];p?openModal(contractModal(p.id)):toast('Create a project first.','error');};});
  $$('[data-action="print-card"]').forEach(b=>b.onclick=()=>window.print());

  $$('[data-approve-user]').forEach(b=>b.onclick=()=>runAction(async()=>{const uid=b.dataset.approveUser,u=state.workspace.users.find(x=>x.id===uid),roles=$$(`[data-role-box="${uid}"]`).filter(x=>x.checked).map(x=>x.value);if(!roles.length)throw new Error('Grant at least one role.');const clientId=$(`[data-client-link="${uid}"]`)?.value||'';await approveUser(uid,{roles,defaultWorkspace:roles[0]});if(roles.includes('client'))await ensureClientLinkForUser(u,clientId);toast('Account approved. Roles remain editable.');},b));
  $$('[data-reject-user]').forEach(b=>b.onclick=()=>runAction(async()=>{if(confirm('Reject this account request?')){await rejectUser(b.dataset.rejectUser);toast('Account rejected.');}},b));
  $$('[data-worker-card]').forEach(b=>{const u=state.workspace.users.find(x=>x.id===b.dataset.workerCard);b.onclick=()=>u&&openModal(workerCardModal(u));});
  $$('[data-manage-account]').forEach(b=>{const u=state.workspace.users.find(x=>x.id===b.dataset.manageAccount);b.onclick=()=>u&&openModal(accountAccessModal(u));});

  $$('[data-action="remove-profile-photo"]').forEach(b=>b.onclick=()=>runAction(async()=>{if(!confirm('Remove your current profile picture?'))return;await updateUserProfile(state.authUser.uid,{profilePhotoUrl:''});state.profile={...state.profile,profilePhotoUrl:''};toast('Profile picture removed.');render();},b));
  $$('[data-action="cleanup-test-data"]').forEach(b=>b.onclick=()=>runAction(async()=>{if(!isMainOwner())return;const phrase=prompt('This permanently deletes records explicitly marked as test data and their linked records. Type DELETE TEST DATA to continue.');if(phrase!=='DELETE TEST DATA')return;const result=await cleanupTestData();toast(`Deleted ${result.projects} test project(s), ${result.related} linked record(s), and ${result.clients} unused test client(s).`);render();},b));

  bindShared(document);
  bindForms(document);
}
function bindModal(){
  const layer=$('.project-layer');
  if(!layer)return;
  bindShared(layer);
  $$('[data-project-tab]',layer).forEach(b=>b.onclick=()=>{const p=projectById(state.activeProjectId);$$('[data-project-tab]',layer).forEach(x=>x.classList.toggle('active',x===b));const body=$('#project-tab-body',layer);if(!body||!p)return;const tab=b.dataset.projectTab;body.innerHTML=tab==='tasks'?projectTasksTab(p):tab==='moodboard'?projectMoodboardTab(p):tab==='commercial'?projectCommercialTab(p):tab==='reviews'?projectReviewsTab(p):tab==='delivery'?projectDeliveryTab(p):projectOverviewTab(p,tasksFor(p.id),contractFor(p.id),invoicesFor(p.id),invoicesFor(p.id).reduce((sum,i)=>sum+Number(i.paidAmount||0),0));bindShared(body);});
}
function registrationTrainingView(){const requested=state.profile?.requestedRole;const role=rolesOf().length?effectiveRole():(requested==='client'?'client':'worker');const key=['owner','admin'].includes(role)?'owner':role==='client'?'client':'worker',steps=onboardingByRole[key]||onboardingByRole.worker,i=Math.min(state.tourStep,steps.length-1),step=steps[i];return `<div class="registration-tour-stage"><div class="registration-tour-card">${logo('large')}<span class="eyebrow">First-time StudioDesk orientation</span><div class="tour-counter">${i+1} / ${steps.length}</div><h1>${esc(step[1])}</h1><p>${esc(step[2])}</p><div class="tour-progress"><span style="width:${((i+1)/steps.length)*100}%"></span></div><div class="button-row"><button class="glass-button" data-tour-prev ${i===0?'disabled':''}>Previous</button><button class="primary-button liquid-action" data-tour-next>${i===steps.length-1?'Finish orientation':'Continue'}</button></div><small>This orientation appears once when an account is newly registered. It has no replay section afterward.</small></div></div>`;}
function startTraining(){state.tourStep=0;render();}
async function startWorkspace(){if(state.workspaceUnsub){try{state.workspaceUnsub()}catch{}state.workspaceUnsub=null;}state.workspace=emptyWorkspace();if(!state.authUser||state.authUser.isAnonymous||!state.profile)return;state.settings=await getStudioSettings().catch(()=>null);if(isOwner())state.workspaceUnsub=await subscribeOwnerWorkspace(data=>{state.workspace={...state.workspace,...data};render();});else{const role=actualRole(),scopedProfile={...state.profile,role,roles:[role],defaultWorkspace:role};state.workspaceUnsub=await subscribeRoleWorkspace(scopedProfile,data=>{state.workspace={...state.workspace,...data};render();});}}
async function bootstrap(){
  state.connection=await firebaseConnectionStatus();
  subscribeCollection('catalogAssets',rows=>{state.publicServices=rows.filter(x=>x.published);if(!state.authUser)render();},{where:['published','==',true],limit:100}).catch(()=>{});
  await watchAuth(async user=>{
    if(state.profileUnsub){try{state.profileUnsub()}catch{}state.profileUnsub=null;}
    state.authUser=user;state.profile=null;state.workspaceRole=null;state.authReady=true;state.tourStep=0;
    if(user&&!user.isAnonymous){
      state.profile=await getCurrentUserProfile().catch(()=>null);
      const saved=sessionStorage.getItem('studiodeskWorkspaceRole');
      if(saved&&rolesOf(state.profile).includes(saved))state.workspaceRole=saved;else sessionStorage.removeItem('studiodeskWorkspaceRole');
      if(state.profile?.status==='active'&&state.route==='login')state.route='dashboard';
    }
    await startWorkspace();render();
    if(user&&!user.isAnonymous){
      state.profileUnsub=await subscribeCurrentUserProfile(async next=>{
        const before=JSON.stringify({roles:rolesOf(state.profile),status:state.profile?.status||'',clientId:state.profile?.clientId||'',defaultWorkspace:state.profile?.defaultWorkspace||''});
        const after=JSON.stringify({roles:rolesOf(next),status:next?.status||'',clientId:next?.clientId||'',defaultWorkspace:next?.defaultWorkspace||''});
        state.profile=next;
        if(state.workspaceRole&&!rolesOf(next).includes(state.workspaceRole)){state.workspaceRole=null;sessionStorage.removeItem('studiodeskWorkspaceRole');}
        if(before!==after)await startWorkspace();
        render();
      });
    }
  });
}
bootstrap().catch(err=>{console.error(err);state.authReady=true;state.connection={ready:false,label:'Connection error'};state.loginMessage=err?.message||'StudioDesk could not start.';render();});
